tool.command:

  ln -f -s ${input_path} ${input_path}_`echo $$`.${input_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

acpype_params_gmx

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__basename__dq__:__dq__${properties.basename}__dq__,__dq__charge__dq__:${properties.charge},__dq__charge_method__dq__:__dq__${properties.charge_method}__dq__,__dq__multiplicity__dq__:${properties.multiplicity},__dq__atom_type__dq__:__dq__${properties.atom_type}__dq__,__dq__protein_ff__dq__:__dq__${properties.protein_ff}__dq__,__dq__qprog__dq__:__dq__${properties.qprog}__dq__,__dq__keyword__dq__:__dq__${properties.keyword}__dq__,__dq__max_time__dq__:${properties.max_time},__dq__predindex__dq__:__dq__${properties.predindex}__dq__,__dq__gmx4__dq__:${properties.gmx4},__dq__merge__dq__:${properties.merge},__dq__sorted__dq__:${properties.sorted},__dq__binary_path__dq__:__dq__${properties.binary_path}__dq____cc____cc__'
  #end if

  #if str($input_path) != 'None':
    --input_path ${input_path}_`echo $$`.${input_path.ext}
  #end if


  --output_path_gro $outname_output_path_gro

  --output_path_itp $outname_output_path_itp

  --output_path_top $outname_output_path_top
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_path}_`echo $$`.${input_path.ext};


  if test -f $outname_output_path_gro; then mv $outname_output_path_gro $output_path_gro; fi;

  if test -f $outname_output_path_itp; then mv $outname_output_path_itp $output_path_itp; fi;

  if test -f $outname_output_path_top; then mv $outname_output_path_top $output_path_top; fi;
